expressionInfos.expression:
//Recodes Size/Density numeric code into same text as used in legend
var code = $feature.SizeDensity;
return Decode(code, 
  1, 'Low density sapling', 
  2, 'Medium density sapling', 
  3, 'High density sapling', 
  4, 'Low density pole', 
  5, 'Medium density pole', 
  6, 'High density pole', 
  7, 'Low density log', 
  8, 'Medium density log', 
  9, 'High density log', 
  'Unknown'
  );

labelExpressionInfo.expression:
//Recodes LineTitle into label text
var code = $feature.OBJECTID;
return IIf(code==1,'↑Zone 2 — ↓Zone 3',Iif(code==5,'↑Zone 1 — ↓Zone 2','UNKNOWN'));

